mapper.sql:
WITH filtered_sessions AS MATERIALIZED ( SELECT s.tenant_id, t.name AS tenant_name, s.session_id, s.end_user_id AS user_id, u.display_name AS user_name, CASE WHEN s.agent_id IS NOT NULL THEN 'AGENT' ELSE 'TEAM' END AS target_type, s.agent_id, a.name AS agent_name, s.team_id, COALESCE(team.definition ->> 'name', team.id) AS team_name, s.channel_id, c.channel_type, c.name AS channel_name, s.summary_text, s.message_count, s.active_execution_id, s.expired_at, s.created_at, s.updated_at FROM public.nw_chat_sessions s JOIN public.nw_tenants t ON t.id = s.tenant_id JOIN public.nw_end_users u ON u.tenant_id = s.tenant_id AND u.id = s.end_user_id LEFT JOIN public.nw_agents a ON a.tenant_id = s.tenant_id AND a.id = s.agent_id LEFT JOIN public.nw_agent_teams team ON team.tenant_id = s.tenant_id AND team.id = s.team_id LEFT JOIN public.nw_channels c ON c.tenant_id = s.tenant_id AND c.id = s.channel_id
AND s.tenant_id=#{scopeTenantId} AND s.tenant_id=#{tenantId} AND s.session_id=#{sessionId} AND s.end_user_id=#{userId} AND s.agent_id=#{agentId} AND s.team_id=#{teamId} AND (c.channel_type=#{channel} OR c.name ILIKE '%'||#{channel}||'%' OR s.channel_id::text=#{channel}) AND s.created_at>=#{startedFrom} AND s.created_at<#{startedTo} AND s.summary_text ILIKE '%'||#{summary}||'%'
), event_roots AS ( SELECT event.tenant_id, event.session_id, event.root_input_id, MAX(event.session_sequence) AS last_sequence, MAX(to_timestamp(event.occurred_at_epoch_second + event.occurred_at_nano / 1000000000.0)) AS last_event_at FROM () event JOIN filtered_sessions session ON event.tenant_id=session.tenant_id::text AND event.session_id=session.session_id GROUP BY event.tenant_id, event.session_id, event.root_input_id ), latest_roots AS ( SELECT DISTINCT ON (tenant_id, session_id) tenant_id, session_id, root_input_id, last_sequence FROM event_roots ORDER BY tenant_id, session_id, last_sequence DESC ), message_stats AS ( SELECT message.tenant_id, message.session_id, MIN(message.created_at) AS first_message_at, MAX(message.created_at) AS last_message_at, COUNT(*)::integer AS visible_memory_count, MAX(message.id) AS message_upper_bound FROM public.nw_chat_messages message JOIN filtered_sessions session ON session.tenant_id=message.tenant_id AND session.session_id=message.session_id LEFT JOIN latest_roots root ON root.tenant_id=message.tenant_id::text AND root.session_id=message.session_id GROUP BY message.tenant_id, message.session_id ), event_stats AS ( SELECT tenant_id, session_id, COUNT(*)::integer AS root_input_count, MAX(last_event_at) AS last_event_at FROM event_roots GROUP BY tenant_id, session_id ), current_run_ids AS ( SELECT run.tenant_id, run.session_id, run.run_id FROM public.agent_runtime_execution_runs run JOIN filtered_sessions session ON run.tenant_id=session.tenant_id::text AND run.session_id=session.session_id WHERE run.status IN ('QUEUED','RUNNING','RESUMING','SUSPENDED') UNION SELECT DISTINCT event.tenant_id, event.session_id, event.run_id FROM () event JOIN latest_roots root ON root.tenant_id=event.tenant_id AND root.session_id=event.session_id AND root.root_input_id=event.root_input_id WHERE event.run_id IS NOT NULL ), run_stats AS ( SELECT run.tenant_id, run.session_id, bool_or(run.status IN ('QUEUED','RUNNING','RESUMING') AND run.phase<>'UNCERTAIN') AS has_running, bool_or(run.status = 'SUSPENDED' AND run.phase<>'UNCERTAIN') AS has_waiting, bool_or(run.status IN ('FAILED','TERMINATED')) AS has_failed, bool_or(run.status = 'CANCELLED') AS has_cancelled, bool_or(run.phase = 'UNCERTAIN') AS has_unknown, COUNT(*) > 0 AS has_runs FROM public.agent_runtime_execution_runs run JOIN current_run_ids current ON current.tenant_id=run.tenant_id AND current.session_id=run.session_id AND current.run_id=run.run_id GROUP BY run.tenant_id, run.session_id ), candidates AS ( SELECT session.tenant_id, session.tenant_name, session.session_id, session.user_id, session.user_name, session.target_type, session.agent_id, session.agent_name, session.team_id, session.team_name, session.channel_id, session.channel_type, session.channel_name, CASE WHEN COALESCE(rs.has_running, false) OR COALESCE(rs.has_waiting, false) THEN 'IN_PROGRESS' WHEN COALESCE(rs.has_failed, false) OR COALESCE(rs.has_unknown, false) THEN 'FAILED' ELSE 'NONE' END AS answer_status, CASE WHEN COALESCE(rs.has_running, false) THEN 'RUNNING' WHEN COALESCE(rs.has_waiting, false) THEN 'WAITING' WHEN COALESCE(rs.has_failed, false) THEN 'FAILED' WHEN COALESCE(rs.has_cancelled, false) THEN 'CANCELLED' WHEN COALESCE(rs.has_unknown, false) THEN 'OUTCOME_UNKNOWN' WHEN COALESCE(rs.has_runs, false) THEN 'COMPLETED' ELSE 'IDLE' END AS execution_status, session.summary_text, COALESCE(ms.visible_memory_count, 0) AS message_count, COALESCE(es.root_input_count, 0) AS root_input_count, latest.root_input_id AS latest_root_input_id, COALESCE(latest.last_sequence, 0) AS event_upper_bound, COALESCE(ms.message_upper_bound, 0) AS message_upper_bound, session.active_execution_id, session.expired_at, ms.first_message_at, ms.last_message_at, session.created_at, session.updated_at, GREATEST(session.updated_at, COALESCE(ms.last_message_at, session.updated_at), COALESCE(es.last_event_at, session.updated_at)) AS last_activity_at FROM filtered_sessions session LEFT JOIN latest_roots latest ON latest.tenant_id=session.tenant_id::text AND latest.session_id=session.session_id LEFT JOIN message_stats ms ON ms.tenant_id=session.tenant_id AND ms.session_id=session.session_id LEFT JOIN event_stats es ON es.tenant_id=session.tenant_id::text AND es.session_id=session.session_id LEFT JOIN run_stats rs ON rs.tenant_id=session.tenant_id::text AND rs.session_id=session.session_id )

mapper.select:
SELECT MAX(session_sequence)
  FROM () event
 WHERE tenant_id=#{tenantId} AND session_id=#{sessionId}

sql.foreach:
(event.tenant_id=CAST(#{scope.tenantId} AS text) AND event.session_id=#{scope.sessionId}
 AND event.session_sequence<=#{scope.eventUpperBound}

   AND event.root_input_id IN #{root}
 )

mapper.select:
SELECT message.tenant_id,message.session_id,message.id,message.message_id,message.role,message.content, COALESCE(message.metadata->>'root_input_id',message.metadata->>'rootInputId') AS root_input_id, COALESCE(message.metadata->>'run_id',message.metadata->>'runId') AS run_id, message.metadata->>'phase' AS phase,message.metadata->>'state' AS state, message.metadata->>'team_answer_ref' AS team_answer_ref,message.message_version, message.metadata::text AS metadata_json,message.input_references::text AS references_json,message.created_at FROM public.nw_chat_messages message WHERE (message.tenant_id=#{scope.tenantId} AND message.session_id=#{scope.sessionId} AND message.id<=#{scope.messageUpperBound}
AND COALESCE(message.metadata->>'root_input_id',message.metadata->>'rootInputId') IN #{root} )
ORDER BY message.created_at,message.id

SELECT MAX(session_sequence)
  FROM () event
 WHERE tenant_id=#{tenantId} AND session_id=#{sessionId} AND root_input_id=#{rootInputId,jdbcType=VARCHAR}

SELECT session_sequence
  FROM () event
 WHERE tenant_id=#{tenantId} AND session_id=#{sessionId} AND root_input_id=#{rootInputId,jdbcType=VARCHAR}
   AND event_id=#{nodeId} AND session_sequence<=#{upperBound}

SELECT COUNT(*)
  FROM () event
 WHERE tenant_id=#{tenantId} AND session_id=#{sessionId} AND root_input_id=#{rootInputId,jdbcType=VARCHAR}
   AND event_id=#{eventId}
